using System.Text.Json.Nodes;
using RaidActions.Execution;
using RaidExtractor;

namespace RaidActions.Game.Memory;

/// <summary>Where the live game's offsets and raid-extractor's read-only files are.</summary>
/// <param name="RaidExtractorRoot">raid-extractor's folder: its config/offsets.json and config/display-names.json are read, never written.</param>
/// <param name="UiOffsets">config/ui-offsets.json (generated by scripts/gen-ui-offsets.ps1).</param>
/// <param name="UiOffsetsManual">config/ui-offsets.manual.json.</param>
/// <param name="Output">This app's output folder: the merged offsets and the live reads go here.</param>
public sealed record LiveGamePaths(string RaidExtractorRoot, string UiOffsets, string UiOffsetsManual, string Output);

/// <summary>
/// The running game, read-only (RaidExtractor.Core's session: PROCESS_VM_READ, game binary hash checked against the offsets):
/// fresh account reads (Core's exporter) and the UI state. Core's offsets and this repo's UI offsets must come from the same build.
/// </summary>
public sealed class LiveGame : IDisposable
{
    private readonly GameSession _session;
    private readonly OffsetConfig _offsets;
    private readonly LiveGamePaths _paths;
    private readonly object _lock = new();

    private LiveGame(GameSession session, OffsetConfig offsets, LiveGamePaths paths, ProcessMemory raw)
    {
        _session = session;
        _offsets = offsets;
        _paths = paths;
        Raw = raw;
        Objects = new CoreObjects(session, offsets);
    }

    /// <summary>Raw read-only memory (Core's ProcessMemory: PROCESS_VM_READ only) for Unity's native objects.</summary>
    public ProcessMemory Raw { get; }

    /// <summary>The game's managed objects by the names in the offsets.</summary>
    public IGameObjects Objects { get; }

    public OffsetConfig Offsets => _offsets;

    /// <summary>Unity UI from memory, with the native layouts in <paramref name="nativeLayoutPath"/> (config/ui-native.json).</summary>
    public UnityUi Ui(string nativeLayoutPath)
    {
        var layout = NativeLayout.Load(nativeLayoutPath);
        if (layout.GameVersion != _offsets.GameVersion)
            throw new UiReadException($"{nativeLayoutPath} is for game {layout.GameVersion}, the game is {_offsets.GameVersion}: re-check the native layouts (RaidActions probe).");
        return new UnityUi(new RawMemory(Raw), layout, Objects);
    }

    private sealed class RawMemory(ProcessMemory m) : INativeMemory
    {
        public bool TryRead(ulong address, Span<byte> buffer) => m.TryRead(address, buffer);
    }

    public string GameVersion => _offsets.GameVersion;

    public static (LiveGame? Game, string? Problem) Open(LiveGamePaths paths)
    {
        var (merged, problem) = MergeOffsets(paths);
        if (merged is null) return (null, problem);
        var file = Path.Combine(paths.Output, "runtime", "offsets-merged.json");
        Directory.CreateDirectory(Path.GetDirectoryName(file)!);
        File.WriteAllText(file, merged.ToJsonString());
        var offsets = OffsetConfig.Load(file);
        var open = GameSession.TryOpen(offsets);
        if (open.Session is null) return (null, open.Message);
        var pid = System.Diagnostics.Process.GetProcessesByName("Raid").Single().Id;
        return (new LiveGame(open.Session, offsets, paths, new ProcessMemory(pid)), null);
    }

    /// <summary>Core's offsets with this repo's UI roots, types, enums and reviewed manual fields added. Refused when the builds differ.</summary>
    public static (JsonObject? Merged, string? Problem) MergeOffsets(LiveGamePaths paths)
    {
        var corePath = Path.Combine(paths.RaidExtractorRoot, "config", "offsets.json");
        if (!File.Exists(corePath)) return (null, $"{corePath} not found.");
        if (!File.Exists(paths.UiOffsets)) return (null, $"{paths.UiOffsets} not found: run scripts/gen-ui-offsets.ps1.");
        var core = JsonNode.Parse(File.ReadAllText(corePath))!.AsObject();
        var ui = JsonNode.Parse(File.ReadAllText(paths.UiOffsets))!.AsObject();
        string Hash(JsonObject o) => (string?)o["build"]?["binarySha256"] ?? "";
        string Version(JsonObject o) => (string?)o["build"]?["gameVersion"] ?? "?";
        if (!string.Equals(Hash(core), Hash(ui), StringComparison.OrdinalIgnoreCase))
            return (null, $"config/ui-offsets.json is for game {Version(ui)}, raid-extractor's offsets for {Version(core)}: re-run scripts/gen-ui-offsets.ps1 after raid-extractor's new dump.");

        foreach (var section in new[] { "roots", "types", "enums" })
        {
            var target = core[section]?.AsObject() ?? throw new InvalidDataException($"{corePath} has no {section}.");
            foreach (var (k, v) in ui[section]!.AsObject())
            {
                if (target.ContainsKey(k)) return (null, $"{section}.{k} is in both raid-extractor's offsets and config/ui-offsets.json.");
                target[k] = v!.DeepClone();
            }
        }
        if (File.Exists(paths.UiOffsetsManual))
        {
            var manual = JsonNode.Parse(File.ReadAllText(paths.UiOffsetsManual))!.AsObject();
            if ((string?)manual["build"]?["gameVersion"] != Version(core))
                return (null, $"{paths.UiOffsetsManual} is for game {(string?)manual["build"]?["gameVersion"]}, not {Version(core)}: re-check its offsets.");
            var types = core["types"]!.AsObject();
            foreach (var (key, spec) in manual["fields"]!.AsObject())
            {
                var dot = key.LastIndexOf('.');
                var (type, member) = (key[..dot], key[(dot + 1)..]);
                var t = types[type]?.AsObject() ?? (JsonObject)(types[type] = new JsonObject { ["kind"] = "class", ["offsetsRelativeTo"] = "object", ["fields"] = new JsonObject() });
                t["fields"]!.AsObject()[member] = new JsonObject
                {
                    ["offset"] = (string)spec!["offset"]!, ["type"] = (string)spec["type"]!, ["field"] = member, ["source"] = "manual", ["status"] = (string)spec["status"]!,
                };
            }
        }
        return (core, null);
    }

    /// <summary>The UI state, read until two consecutive reads agree (the game changes its UI while we read).</summary>
    public (UiState? State, string? Problem) ReadUi()
    {
        lock (_lock)
        {
            var reader = new UiStateReader(new CoreObjects(_session, _offsets));
            string? last = null;
            UiState? previous = null;
            for (var i = 0; i < 6; i++)
            {
                try
                {
                    var s = reader.Read();
                    if (previous is not null && Same(previous, s)) return (s, null);
                    previous = s;
                    last = "the UI changed between reads";
                }
                catch (Exception e) when (e is UiReadException or ReadCheckException or KeyNotFoundException)
                {
                    previous = null;
                    last = e.Message;
                }
                Thread.Sleep(40);
            }
            return (null, last);
        }
    }

    private static bool Same(UiState a, UiState b) =>
        a.Views.SequenceEqual(b.Views) && a.BlockingEvents == b.BlockingEvents && Equals(a.ChampionScreen, b.ChampionScreen);

    /// <summary>A fresh account read through Core's exporter, written to output/live (never to raid-extractor).</summary>
    public IAccountSource Account => new LiveAccount(this);

    private sealed class LiveAccount(LiveGame game) : IAccountSource
    {
        public Task<SavedExport> ReadAsync(CancellationToken ct) => Task.Run(() =>
        {
            ct.ThrowIfCancellationRequested();
            lock (game._lock)
            {
                var dir = Path.Combine(game._paths.Output, "live");
                var names = Path.Combine(game._paths.RaidExtractorRoot, "config", "display-names.json");
                var r = Exporter.Export(new Account(game._session, game._offsets), dir, names, historyMinInterval: TimeSpan.FromHours(1));
                if (!r.Ok || r.Data is null) throw new InvalidOperationException("Live account read failed: " + r.Message);
                return r.Data;
            }
        }, ct);
    }

    public void Dispose()
    {
        Raw.Dispose();
        _session.Dispose();
    }
}

/// <summary><see cref="IGameObjects"/> on RaidExtractor.Core's reader (every read bounds- and pointer-checked by Core).</summary>
internal sealed class CoreObjects(GameSession session, OffsetConfig offsets) : IGameObjects
{
    private Il2CppReader R => session.Reader;

    public ulong Root(string name, string expectedType) => session.ResolveRoot(name, expectedType);
    private readonly Dictionary<ulong, IReadOnlyList<string>> _chains = [];

    public string ClassName(ulong obj) => ClassChain(obj)[0];

    public IReadOnlyList<string> ClassChain(ulong obj)
    {
        var klass = R.ReadPointer(obj + (ulong)offsets.Il2Cpp("object", "klass"), "object.klass");
        if (_chains.TryGetValue(klass, out var known)) return known;
        var names = new List<string>();
        for (var k = R.ReadClass(klass); ; k = R.ReadClass(k.Parent))
        {
            names.Add(k.FullName);
            if (k.Parent == 0 || names.Count > 32) break;
        }
        return _chains[klass] = names;
    }

    public bool Bool(ulong obj, string type, string member) => R.ReadBoolField(obj, offsets.Field(type, member));
    public ulong Ref(ulong obj, string type, string member) => R.ReadPointerOrNull(obj + (ulong)offsets.Field(type, member).Offset, $"{type}.{member}");
    public int Int(ulong obj, string type, string member) => R.ReadInt32(obj + (ulong)offsets.Field(type, member).Offset, $"{type}.{member}");
    public int? NullableInt(ulong obj, string type, string member) => R.ReadNullableInt32(obj + (ulong)offsets.Field(type, member).Offset, $"{type}.{member}");
    public IReadOnlyList<ulong> RefList(ulong list, int max) => R.ReadReferenceList(list, max, "list");
    public string? EnumName(string enumType, int value) => offsets.Enum(enumType).TryGetValue(value, out var n) ? n : null;
}
